code.text:
:root {
  --cor-fundo: #0b1020;
  --cor-texto: #e8ecf8;
  --cor-destaque: #5eead4;
}

body {
  background: var(--cor-fundo);
  color: var(--cor-texto);
  font-family: system-ui, sans-serif;
}

.timeline {
  display: grid;
  gap: 1.5rem;
}

const form = document.querySelector("#contato form");

form?.addEventListener("submit", (event) => {
  event.preventDefault();
  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }
  // Envie os dados com EmailJS ou outro serviço de e-mail.
  form.reset();
});

@media (max-width: 640px) {
  nav a {
    display: block;
    padding: 0.75rem 0;
  }

  .timeline {
    grid-template-columns: 1fr;
  }
}
